    elapsed = time.perf_counter() - t0

    try:
        os.remove(runner_path)
    except OSError:
        pass

    errors = [(i, r[0]) for i, r in enumerate(thread_results)
              if isinstance(r[0], Exception)]
    if errors:
        for i, e in errors:
            print(f"Error on seed {i}: {e}")
        sys.exit(1)

    valid = [r[0] for r in thread_results if isinstance(r[0], dict)]
    if not valid:
        print("All evaluations failed.")
        sys.exit(1)

    eval_labels = [k for k in sorted(valid[0]) if k != "time_s"]
    averaged = {}
    for label in eval_labels:
        averaged[label] = {
            "mean_r":  round(sum(r[label]["mean_r"]  for r in valid) / len(valid), 4),
            "k562_r":  round(sum(r[label]["k562_r"]  for r in valid) / len(valid), 4),
            "hepg2_r": round(sum(r[label]["hepg2_r"] for r in valid) / len(valid), 4),
            "sknsh_r": round(sum(r[label]["sknsh_r"] for r in valid) / len(valid), 4),
        }
    averaged["n_seeds"] = len(valid)
    averaged["time_s"]  = round(elapsed, 1)
    averaged["seeds"]   = [{label: r[label] for label in eval_labels} for r in valid]

    result_path = os.path.join(exp_dir, "result.json")
    with open(result_path, "w") as f:
        json.dump(averaged, f, indent=2)

    _print_results(averaged, result_path, elapsed)


